/**
 * Cloudy CLI — design tokens.
 * GENERATED by theme/build.mjs from theme/tokens.mjs — do not edit by hand.
 *
 * Terminal roles mapped onto the shared token set. Ink takes a colour per
 * prop, so each role resolves to a canonical value: no file under cli/src
 * names a colour of its own.
 *
 *   role        canonical token
 *   bg          #000000
 *   text        --text
 *   dim         dimColor
 *   accent      --accent
 *   onAccent    --bg
 *   border      --border-strong
 *   ctaBg       --accent
 *   ctaInk      --accent-ink
 *   adBorder    --advertiser-accent-default
 *   adCta       --advertiser-accent-default
 *   adCtaInk    --accent-ink
 *   modelDot    --model-accent-default
 */

export const TUI = {
  bg: "#000000",
  text: "#f2f3f5",
  dim: "dimColor",
  accent: "#ffffff",
  onAccent: "#0b0b0b",
  border: "#3a3a3a",
  ctaBg: "#ffffff",
  ctaInk: "#000000",
  adBorder: "#6ea8fe",
  adCta: "#6ea8fe",
  adCtaInk: "#000000",
  modelDot: "#9aa0a8",
};

/**
 * Per-model accent dots, keyed by the token name the model registry states for
 * each model (lib/models.ts, whose accents name the tokens in theme/tokens.mjs).
 * A model that names no accent gets TUI.modelDot.
 */
export const MODEL_ACCENTS = {
  "--model-accent-muse": "#8b5cf6",
  "--model-accent-mimo": "#f59e0b",
  "--model-accent-glm": "#38bdf8",
  "--model-accent-ling": "#f97316",
  "--model-accent-ling-vl": "#fb923c",
  "--model-accent-gpt": "#34d399",
  "--model-accent-deepseek": "#60a5fa",
  "--model-accent-deepseek-v41": "#3b82f6",
  "--model-accent-solar": "#a78bfa",
  "--model-accent-default": "#9aa0a8",
};

/** True when stdout is a TTY; callers gate ANSI on this. */
export const TTY = !!process.stdout.isTTY;

/** Dim/bold/reset codes for the plain (non-Ink) renderer in ui.js. */
export const ANSI = {
  reset: TTY ? "\x1b[0m" : "",
  dim: TTY ? "\x1b[2m" : "",
  bold: TTY ? "\x1b[1m" : "",
};

